(()=>{
 const key='tsoie-cookie-preferences',version=1,duration=180*86400000;
 function stored(){try{const p=JSON.parse(localStorage.getItem(key)||'null');return p&&p.version===version&&p.expiresAt>Date.now()?p:null;}catch{return null;}}
 const notice=document.createElement('section');notice.className='cookie-notice';notice.setAttribute('aria-label','Cookie notice');notice.innerHTML=`<div class="cookie-notice-heading">Your privacy, considered.</div><p>We use necessary cookies and storage to remember your cart, secure sign-in and support checkout. We do not currently use optional analytics or advertising cookies. <a href="/#/cookies">Read our cookie notice</a>.</p><div class="cookie-actions"><button data-cookie-choice="all">Accept all</button><button data-cookie-choice="necessary">Reject optional</button><button data-cookie-settings>Settings</button></div>`;
 const dialog=document.createElement('dialog');dialog.className='cookie-dialog';dialog.setAttribute('aria-labelledby','cookie-settings-title');dialog.innerHTML=`<div class="cookie-dialog-heading"><h2 id="cookie-settings-title">Cookie settings</h2><button data-cookie-close aria-label="Close cookie settings">×</button></div><p>You control optional cookies. Necessary cookies and storage keep the shop secure and working.</p><div class="cookie-category"><div><strong>Strictly necessary</strong><p>Cart storage, admin sessions, your preference and payment security. These cannot be switched off here.</p></div><span>Always active</span></div><div class="cookie-category"><div><strong>Analytics & advertising</strong><p>No optional analytics or advertising trackers are currently installed. Accepting all does not activate any tracking.</p></div><span>Not used</span></div><p>Your choice is remembered for 180 days. You can reopen these settings from the footer. <a href="/#/privacy">Privacy notice</a></p><div class="cookie-actions"><button data-cookie-choice="all">Accept all</button><button data-cookie-choice="necessary">Reject optional</button></div>`;
 function save(choice){const value={version,choice,necessary:true,optional:false,savedAt:Date.now(),expiresAt:Date.now()+duration};try{localStorage.setItem(key,JSON.stringify(value));}catch{}notice.hidden=true;if(dialog.open)dialog.close();window.dispatchEvent(new CustomEvent('tsoie:cookie-preferences',{detail:value}));}
 window.openCookieSettings=()=>dialog.showModal();document.body.append(notice,dialog);notice.hidden=Boolean(stored());
 for(const root of [notice,dialog]){root.querySelectorAll('[data-cookie-choice]').forEach(button=>button.addEventListener('click',()=>save(button.dataset.cookieChoice)));root.querySelectorAll('[data-cookie-settings]').forEach(button=>button.addEventListener('click',window.openCookieSettings));}
 dialog.querySelector('[data-cookie-close]').addEventListener('click',()=>dialog.close());
})();
